# 项目须知
590a0bb 实现待办 CLI（含 node:test 测试与使用说明）
{
  "name": "todo-cli",
  "version": "1.0.0",
  "scripts": {
    "test": "node --test"
  },
  "bin": {
    "todo": "todo.js"
  }
}
#!/usr/bin/env node
const fs = require('node:fs');
const path = require('node:path');
const os = require('node:os');

const file = process.env.TODO_FILE || path.join(os.homedir(), '.todos.json');
const usage = `用法：
  todo add <内容...>  添加待办
  todo list          列出待办
  todo done <编号>   完成待办
  todo help          显示用法
也可使用 node todo.js 替代 todo。`;

function load() {
  try {
    return JSON.parse(fs.readFileSync(file, 'utf8'));
  } catch (error) {
    if (error.code === 'ENOENT') return { nextId: 1, items: [] };
    throw error;
  }
}

function save(data) {
  const temporary = path.join(path.dirname(file), `.${path.basename(file)}.${process.pid}.${Date.now()}.tmp`);
  const descriptor = fs.openSync(temporary, 'wx', 0o600);
  try {
    try {
      fs.writeFileSync(descriptor, `${JSON.stringify(data, null, 2)}\n`);
    } finally {
      fs.closeSync(descriptor);
    }
    fs.renameSync(temporary, file);
  } finally {
    if (fs.existsSync(temporary)) fs.unlinkSync(temporary);
  }
}

function main() {
  const [command, ...args] = process.argv.slice(2);
  if (!command || command === 'help') {
    console.log(usage);
    return;
  }

  if (command === 'add') {
    const text = args.join(' ').trim();
    if (!text) throw new Error(usage);
    const data = load();
    const item = { id: data.nextId, text, done: false, createdAt: new Date().toISOString() };
    data.items.push(item);
    data.nextId += 1;
    save(data);
    console.log(`已添加 #${item.id} ${item.text}`);
    return;
  }

  if (command === 'list') {
    const data = load();
    if (data.items.length === 0) {
      console.log('暂无待办');
    } else {
      for (const item of data.items.sort((a, b) => a.id - b.id)) {
        console.log(`[${item.done ? 'x' : ' '}] ${item.id}. ${item.text}`);
      }
    }
    return;
  }

  if (command === 'done') {
    const id = Number(args[0]);
    if (args.length !== 1 || !/^\d+$/.test(args[0]) || !Number.isSafeInteger(id) || id <= 0) {
      throw new Error('编号必须是正整数');
    }
    const data = load();
    const item = data.items.find((entry) => entry.id === id);
    if (!item) throw new Error(`待办 #${id} 不存在`);
    if (item.done) {
      console.log(`#${id} 已是完成状态`);
      return;
    }
    item.done = true;
    save(data);
    console.log(`已完成 #${id} ${item.text}`);
    return;
  }

  throw new Error(usage);
}

try {
  main();
} catch (error) {
  console.error(`错误：${error.message}`);
  process.exitCode = 1;
}
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const { spawnSync } = require('node:child_process');

const cli = path.resolve(__dirname, '..', 'todo.js');

function setup(t) {
  const directory = fs.mkdtempSync(path.join(__dirname, 'todo-'));
  t.after(() => fs.rmSync(directory, { recursive: true, force: true }));
  const file = path.join(directory, 'todos.json');
  return {
    file,
    run(...args) {
      const result = spawnSync(process.execPath, [cli, ...args], {
        env: { ...process.env, TODO_FILE: file },
        encoding: 'utf8',
      });
      assert.ifError(result.error);
      assert.equal(result.signal, null);
      return result;
    },
  };
}

function success(result, output) {
  assert.equal(result.status, 0, result.stderr);
  assert.equal(result.stdout, `${output}\n`);
  assert.equal(result.stderr, '');
}

function failure(result, message) {
  assert.equal(result.status, 1);
  assert.equal(result.stdout, '');
  assert.match(result.stderr, message);
}

test('不存在的数据文件视为空清单', (t) => {
  const { run, file } = setup(t);
  success(run('list'), '暂无待办');
  assert.equal(fs.existsSync(file), false);
});

test('add 拼接多个参数并去掉首尾空白，list 显示内容', (t) => {
  const { run } = setup(t);
  success(run('add', '  买', '牛奶  '), '已添加 #1 买 牛奶');
  success(run('list'), '[ ] 1. 买 牛奶');
});

test('独立进程间持久化，编号自增且完成后不复用', (t) => {
  const { run, file } = setup(t);
  success(run('add', '买牛奶'), '已添加 #1 买牛奶');
  success(run('add', '写周报'), '已添加 #2 写周报');
  success(run('done', '1'), '已完成 #1 买牛奶');
  success(run('add', '散步'), '已添加 #3 散步');
  success(run('list'), '[x] 1. 买牛奶\n[ ] 2. 写周报\n[ ] 3. 散步');
  const data = JSON.parse(fs.readFileSync(file, 'utf8'));
  assert.equal(data.nextId, 4);
  assert.deepEqual(data.items.map(({ id, text, done }) => ({ id, text, done })), [
    { id: 1, text: '买牛奶', done: true },
    { id: 2, text: '写周报', done: false },
    { id: 3, text: '散步', done: false },
  ]);
  for (const item of data.items) {
    assert.equal(new Date(item.createdAt).toISOString(), item.createdAt);
  }
  assert.deepEqual(fs.readdirSync(path.dirname(file)), ['todos.json']);
});

test('重复完成成功且不改动数据文件', (t) => {
  const { run, file } = setup(t);
  success(run('add', '买牛奶'), '已添加 #1 买牛奶');
  success(run('done', '1'), '已完成 #1 买牛奶');
  const before = fs.readFileSync(file, 'utf8');
  success(run('done', '1'), '#1 已是完成状态');
  assert.equal(fs.readFileSync(file, 'utf8'), before);
});

test('done 不存在的编号返回 1', (t) => {
  const { run, file } = setup(t);
  failure(run('done', '99'), /不存在/);
  assert.equal(fs.existsSync(file), false);
});

test('done 拒绝缺失编号、非正整数和超出安全范围的编号', (t) => {
  const { run } = setup(t);
  for (const id of [undefined, '0', '-1', '1.5', 'abc', '1abc', '1e2', 'Infinity', '9007199254740992']) {
    failure(id === undefined ? run('done') : run('done', id), /正整数/);
  }
});

test('add 缺少内容或只有空白时输出用法并返回 1', (t) => {
  const { run, file } = setup(t);
  failure(run('add'), /用法/);
  failure(run('add', '  ', '\t'), /用法/);
  assert.equal(fs.existsSync(file), false);
});

test('未知命令输出用法并返回 1', (t) => {
  const { run } = setup(t);
  failure(run('foo'), /用法/);
});

test('无参数和 help 输出用法并返回 0', (t) => {
  const { run, file } = setup(t);
  for (const args of [[], ['help']]) {
    const result = run(...args);
    assert.equal(result.status, 0);
    assert.equal(result.stderr, '');
    assert.match(result.stdout, /用法/);
    assert.match(result.stdout, /add/);
    assert.match(result.stdout, /list/);
    assert.match(result.stdout, /done/);
  }
  assert.equal(fs.existsSync(file), false);
});

test('list 按 id 升序显示', (t) => {
  const { run, file } = setup(t);
  fs.writeFileSync(file, JSON.stringify({ nextId: 3, items: [
    { id: 2, text: '写周报', done: true, createdAt: '2026-01-01T00:00:00.000Z' },
    { id: 1, text: '买牛奶', done: false, createdAt: '2026-01-01T00:00:00.000Z' },
  ] }));
  success(run('list'), '[ ] 1. 买牛奶\n[x] 2. 写周报');
});

test('损坏的数据文件报错且保留原文件', (t) => {
  const { run, file } = setup(t);
  fs.writeFileSync(file, '{broken');
  failure(run('add', '买牛奶'), /错误/);
  assert.equal(fs.readFileSync(file, 'utf8'), '{broken');
});
# 待办 CLI

纯 Node.js、零依赖的命令行待办清单。需要 Node.js 18 或更新版本。

## 运行与安装

在项目目录直接运行，无需安装依赖：

```sh
node todo.js help
node todo.js list
```

也可以在项目目录执行 `npm link`，之后在任意目录用 `todo` 调用，例如 `todo list`。

## 三条命令

下面的示例从空清单开始，按顺序运行：

```text
$ node todo.js add 买牛奶
已添加 #1 买牛奶
$ node todo.js add 写 周报
已添加 #2 写 周报
$ node todo.js list
[ ] 1. 买牛奶
[ ] 2. 写 周报
$ node todo.js done 1
已完成 #1 买牛奶
$ node todo.js list
[x] 1. 买牛奶
[ ] 2. 写 周报
$ node todo.js done 1
#1 已是完成状态
```

`add <内容...>` 用空格拼接内容并去除首尾空白；也可用引号包住内容。编号从 1 开始自增，`list` 按编号升序显示；空清单输出 `暂无待办`。

无参数或 `help` 会显示用法，退出码为 0。空内容、无效或不存在的编号、未知命令会向 stderr 输出错误，退出码为 1。

## 数据位置

默认保存在用户家目录的 `.todos.json`（即 `~/.todos.json`）。每次添加或完成后写入 JSON，关闭终端、重新运行仍然保留数据。写入先使用同目录临时文件，再重命名替换数据文件。

可以用环境变量 `TODO_FILE` 指定其他文件；父目录须已存在。以下为 POSIX shell 用法：

```sh
export TODO_FILE="$PWD/my-todos.json"
node todo.js add 买牛奶
node todo.js list
```

`TODO_FILE` 对 `todo` 命令同样有效；相对路径相对于当前工作目录。取消设置后恢复默认位置：`unset TODO_FILE`。

## 测试

```sh
npm test
```

使用内置 `node:test`，通过独立 Node 进程验证命令。每个用例在项目的 `test` 目录内创建临时目录，并显式设置 `TODO_FILE`，不访问真实家目录的数据，测试结束后清理。

